#!/usr/bin/env python
import argparse,json
from pathlib import Path
import numpy as np,pandas as pd
ROOT=Path(__file__).resolve().parents[1]; parser=argparse.ArgumentParser(); parser.add_argument("--smoke",action="store_true"); args=parser.parse_args(); OUT=ROOT/("outputs/phase7_smoke" if args.smoke else "outputs/phase7"); f=pd.read_csv(OUT/"evaluation/unlocked_subject_metrics.csv"); rng=np.random.default_rng(0); auc=f.auroc.to_numpy(); delta=(f.average_precision-f.prevalence).to_numpy(); boot=np.array([rng.choice(auc,len(auc)).mean() for _ in range(10000)]); bootd=np.array([rng.choice(delta,len(delta)).mean() for _ in range(10000)]); signs=rng.choice([-1,1],size=(10000,len(auc))); p=float((1+np.sum(np.mean((auc-.5)*signs,axis=1)>=np.mean(auc-.5)))/10001); usable=int((f.posterior_usable & (f.rhat_x0_max<=1.05)).sum()); science=(not args.smoke) and usable>=24 and np.quantile(boot,.025)>.5 and p<.05 and np.quantile(bootd,.025)>0
report={"mode":"ENGINEERING_SMOKE_ONLY" if args.smoke else "FULL_PRIMARY","frozen_primary_config_executed":not args.smoke,"subjects_attempted":30,"subjects_completed":len(f),"usable_inference":usable,"mean_AUROC":float(auc.mean()),"AUROC_95CI":np.quantile(boot,[.025,.975]).tolist(),"median_AUROC":float(np.median(auc)),"IQR_AUROC":np.quantile(auc,[.25,.75]).tolist(),"mean_AP":float(f.average_precision.mean()),"mean_prevalence":float(f.prevalence.mean()),"mean_AP_minus_prevalence":float(delta.mean()),"AP_delta_95CI":np.quantile(bootd,[.025,.975]).tolist(),"above_chance_p":p,"engineering_gate":"PASS" if len(f)==30 else "FAIL","convergence_gate":"NOT ASSESSED FROM SMOKE" if args.smoke else ("PASS" if usable>=24 else "FAIL"),"scientific_EZN_gate":"NOT ASSESSED FROM SMOKE" if args.smoke else ("PASS" if science else "NOT PASS"),"legacy_adaptive_tau":{"mean_AUROC":.570,"clear_MAP_convergence":"9/30","status":"NOT PASS"}}
(OUT/"phase7_report.json").write_text(json.dumps(report,indent=2)); print(json.dumps(report,indent=2))
